def get_protocol_handlers(cls, protocol_version=None):
    if protocol_version is None:
        return {version: cls.protocol_handlers[version] for version in cls.protocol_handlers.keys()}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be a tuple")

        if protocol_version in cls.protocol_handlers:
            return {protocol_version: cls.protocol_handlers[protocol_version]}
        else:
            return {}

