def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    def partition(iterable, size):
        return (iterable[i:i + size] for i in range(0, len(iterable), size))

    if not cmd:
        raise ValueError("cmd must be specified")

    if color and not sys.stdout.isatty():
        raise ValueError("color requires a tty")

    if not varargs:
        return (0, b"")

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    max_length = _max_length - len(cmd[0]) - 4

    results = []
    for partition_varargs in partition(varargs, max_length):
        p = subprocess.Popen(
            #cmd + list(partition_varargs),
            cmd,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            **kwargs
        )
        results.append((p, partition_varargs))

    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        futures = [
            executor.submit(p.communicate, b" ".join(varargs)) for p, varargs in results
        ]

        exitcode = 0
        output = b""
        for future in futures:
            p, partition_varargs = future.result()
            output += p.stdout
            exitcode = p.returncode

    return (exitcode, output)

