def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    for i, word in enumerate(cmd):
        if not isinstance(word, str):
            continue
        if word.startswith("#!"):
            shebang_prog = word[2:].split(" ", 1)[0]
            shebang_inf = find_in_path(shebang_prog)
            if shebang_inf is not None:
                cmd[i] = shebang_inf + " " + word[2 + len(shebang_prog) + 1:]
    return cmd

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not isinstance(cmd, list):
        cmd = list(cmd)
    command = cmd[0]
    if os.path.basename(command) == "python":
        cmd[0] = sys.executable
        if hasattr(subprocess, 'msvcrt'):
            cmd.insert(1, '-i')
    elif command =='/bin/sh':
        cmd[0] = 'sh'
    return tuple(cmd)

