    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError(f'Expected maxsize to be an integer or None, got {type(maxsize)}')
    if maxsize is not None and maxsize <= 0:
        raise ValueError('Expected maxsize to be a positive integer, got {maxsize}')

    def wrapper(func):
        cache = OrderedDict()
        stats = LRUCaching.Statistics()

        def inner_func(*args, **kwargs):
            if not typed:
                key = args + tuple(kwargs.items())
            else:
                key = args
            if key in cache:
                stats.hits += 1
            else:
                stats.misses += 1
                cache[key] = func(*args, **kwargs)
                if len(cache) > maxsize:
                    cache.popitem(last=False)
            stats.size = len(cache)
            return cache[key]

        setattr(inner_func, 'cache', cache)
        setattr(inner_func, 'stats', stats)
        return inner_func

    return wrapper

