def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord is None:
        raise Exception("coord cannot be None")
    if weight is None:
        raise Exception("weight cannot be None")
    if not isinstance(weight, int):
        raise Exception("weight must be an integer")
    if weight < 0:
        raise Exception("weight must be non-negative")
    if not isinstance(coord, list):
        raise Exception("coord must be a list")
    if len(coord) != self.num_dimensions:
        raise Exception("coord must have the same number of dimensions as the histogram")
    for i in range(self.num_dimensions):
        if coord[i] < 0 or coord[i] >= self.num_bins[i]:
            return
    self.data[coord[0]][coord[1]][coord[2]] += weight

def _validate_labels(labels):
