def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, schema_field in observer_schema.get('properties', {}).items():
        if field not in response:
            continue

        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]

        # If the field is an object, we need to recursively call this function to
        # update its value
        if isinstance(schema_field, dict) and schema_field.get('type') == 'object':
            last_applied_manifest[field] = {
                k: v
                for k, v in response[field].items()
                if isinstance(v, (str, int, float, bool))
            }

        # If the field is a list, we need to recursively call this function to
        # update its value
        elif isinstance(schema_field, dict) and schema_field.get('type') == 'array':
            last_applied_manifest[field] = []
            for item in response[field]:
                if isinstance(item, dict):
                    # Recursively call this function to update the value of the
                    # list item
                    update_last_applied_manifest_dict_from_resp(
                        item, observer_schema['items'][0], item
                    )

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in last_applied_manifest:
            if field not in response:
                raise KeyError(f"Observed field {field} not present in Kubernetes response")
            last_applied_manifest[field] = response[field]
        elif isinstance(last_applied_manifest[field], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        elif isinstance(last_applied_manifest[field], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema[field], response[field])

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for idx, element in enumerate(last_applied_manifest):
        if isinstance(element, dict):
            update_last_applied_manifest_dict_from_resp(element, observer_schema, response[idx])
        elif isinstance(element, list):
            update_last_applied_manifest_list_from_resp(element, observer_schema, response[idx])

def update_last_applied_manifest_from_resp(last_applied_manifest, observer_schema, response):
    if isinstance(last_applied_manifest, dict):
        update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response)
    elif isinstance(last_applied_manifest, list):
        update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response)
    else:
        raise TypeError("last_applied_manifest must be a dict or a list")

