    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for content_file in inventory.get_all_files(version):
        for logical_path in content_file.logical_paths:
            logical_path_map[logical_path] = content_file
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for file in inventory[version]:
        if file.logical_path not in logical_path_map:
            logical_path_map[file.logical_path] = set()
        logical_path_map[file.logical_path].add(file.content_file)
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check the structure of the fixity block
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if "fixity_block" not in fixity:
        raise ValueError("Fixity block must have a 'fixity_block' key")
    if not isinstance(fixity["fixity_block"], list):
        raise ValueError("Fixity block must be a list of fixity records")

    # Check that only files listed in the manifest are referenced
    for fixity_record in fixity["fixity_block"]:
        if not isinstance(fixity_record, dict):
            raise ValueError("Fixity records must be dictionaries")
        if "file" not in fixity_record:
            raise ValueError("Fixity records must have a 'file' key")
        if fixity_record["file"] not in manifest_files:
            raise ValueError(f"Fixity record refers to file '{fixity_record['file']}', which is not listed in the manifest")

