def _group_files_by_xml_filename(source, xmls, files)

    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    packages = {}
    for xml_filename in xmls:
    files.append(source.joinpath(xml_filename))
    for file in files:
        if file.suffix == '.xml':
            package = file.stem
            if package not in packages:
                packages[package] = [file]
            else:
                packages[package].append(file)
    for package, files_in_package in packages.items():
        for file in files_in_package:
            if file.stem != package:
                files_in_package.remove(file)
    return packages

def _eval_file(prefix, file_path):
    """
    Determines the type of file in the package: 'asset' or 'rendition'.

    Determines the type of file in the package and updates 'packages' with the type and
    the file address being analyzed.

    Parameters
    ----------
    prefix : str
        file XML name without extension
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    file_path = PATH_SEPARATOR.join([file_path, prefix + FILE_EXTENSION])
    try:
        typescript = Ratatosk().guess_filenum(file_path)
        if not typescript:
            return dict(file=file_path, type='asset')
        else:
            return dict(file=file_path, type='rendition')
    except Exception as e:
        return dict(file=file_path, type='null', error=e)

def _eval_file(prefix, file_path):
    """Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.
    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.
    Parameters: prefix (str): nome do arquivo XML sem extensão filename (str): filename file_folder (str): file folder Returns: dict"""
    if prefix == 'rendition':
        type = 'rendition'
        prefix = '.rendition'
    else:
        type = 'asset'
        prefix = ''
    return {
        'type': type,
