def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def _absorb(args):
        if len(args) == 1:
            return args[0]

        a, b = args[0], args[1]

        if a == b or ~a == b:
            return a

        if a == ~b:
            return b

        if ~a == ~b:
            return ~a

        return _absorb(args[1:])

    return _absorb(args)

