    if not isinstance(commands, (list, tuple)):
        commands = [commands]

    if not isinstance(args, (list, tuple)):
        args = [args]

    for command in commands:
        if not isinstance(command, str):
            raise TypeError("Command must be a string, not {}: {}".format(type(command), command))

        if isinstance(args, dict):
            for arg in args:
                if not isinstance(arg, str):
                    raise TypeError("Argument must be a string, not {}: {}".format(type(arg), arg))

        if cwd is not None and not isinstance(cwd, str):
            raise TypeError("cwd must be a string, not {}: {}".format(type(cwd), cwd))

        if env is not None and not isinstance(env, dict):
            raise TypeError("env must be a dictionary, not {}: {}".format(type(env), env))

        subprocess.check_call([command] + args, cwd=cwd, env=env)

