def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """

    # Check if each version has an inventory file
    for version in version_dirs:
        inventory_file = os.path.join(version, 'inventory.json')
        if not os.path.exists(inventory_file):
            raise MissingInventoryError(
                f"Inventory file for version {version} is missing"
            )

        # Keep track of any content digests that are different from the root inventory
        content_digests = []
        for digest in get_digests(inventory_file):
            if digest not in self.root_digests:
                content_digests.append(digest)

        # Save the content digests for this version
        self.version_digests[version] = content_digests

    # Check if the inventories are consistent with the root inventory
    for version, digests in self.version_digests.items():
        for digest in digests:
            if digest not in self.root_digests:
                raise InconsistentInventoryError(
                    f"Inventory for version {version} has digest {digest} which is not present in the root inventory"
                )

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        with open(os.path.join(path, '0=inventory.json'), 'r') as f:
            inventory = json.load(f)
            if 'ocfl_object_id' in inventory:
                return 'object'
            else:
                return 'root'
    except FileNotFoundError:
        return 'file'
    except json.JSONDecodeError:
        return "unreadable inventory"
    except OSError as e:
        return "OS error: " + str(e)

