def deep_merge_nodes(nodes):
    merged_nodes = []
    for key, value in nodes:
        if not isinstance(value, MappingNode):
            # If the value is not a mapping node, we take the last one
            merged_nodes.append((key, value))
        else:
            # If the value is a mapping node, we recursively merge any duplicates
            for existing_key, existing_value in merged_nodes:
                if existing_key == key:
                    # If there is an existing key, we merge the two values
                    existing_value = deep_merge_nodes([(existing_key, existing_value), (key, value)])
                    # And overwrite the existing value
                    merged_nodes[merged_nodes.index((existing_key, existing_value))] = (existing_key, existing_value)
                    break
            else:
                # If there is no existing key, we add the new one
                merged_nodes.append((key, value))
    return merged_nodes

