def bash_completion():
    """Return a bash completion script for the borgmatic command. Produce this by introspecting borgmatic's command-line argument parsers."""
    parser = argparse.ArgumentParser(add_help=False)
    parents = [p for p in parser.parents]
    command = parser.add_subparsers(title='Commands', metavar='')

    for parent in parents:
        for option in parent.options:
            if option.startswith('--'):
                command.add_argument(option, action='store_true', help=parent.get_help_string(option))
            else:
                command.add_argument(option, action='store', help=parent.get_help_string(option))

    return command

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    remaining_arguments = []
    subparser_arguments = {}

    for subparser_name, subparser in subparsers.items():
        specified_arguments = None
        for argument in subparser._get_optional_actions():
            if argument.option_strings:
                for option_string in argument.option_strings:
                    if option_string in unparsed_arguments:
                        specified_arguments = unparsed_arguments.get(option_string)
                        break
            if specified_arguments is not None:
                break
        if specified_arguments is not None:
            subparser_arguments[subparser_name] = subparser.parse_known_args(specified_arguments)
            remaining_arguments.extend(subparser_arguments[subparser_name].remaining_arguments)

    return subparser_arguments, remaining_arguments

