def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """

    result = []
    for i in range(len(vertices)):
        if i == 0:
            result.append((vertices[i], vertices[i+1], vertices[len(vertices)-1]))
        elif i == len(vertices):
            result.append((vertices[i], vertices[0], vertices[i-1]))
        else:
            result.append((vertices[i], vertices[i+1], vertices[i-1]))
    return result

