def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    # find all nodes that have incoming edges
    nodes_with_incoming_edges = set()
    for s, p, o in graph:
        if p == prop:
            nodes_with_incoming_edges.add(s)
    # find all nodes that do not have incoming edges
    roots.clear()
    for s, p, o in graph:
        if s not in nodes_with_incoming_edges:
            roots.add(s)
    return roots

def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    for resource in graph.subjects(prop, None):
        roots.add(resource)
    for resource in graph.subjects(None, prop):
        if resource not in roots:
            find_roots(graph, prop, resource)
    return roots

