    """
    if not isinstance(iface, Interface):
        raise TypeError("The argument 'iface' must be an instance of Interface.")

    if not isinstance(candidate, type) or not issubclass(candidate, object):
        raise TypeError("The argument 'candidate' must be a type.")

    for name, detail in iface.__dict__.items():
        if name.startswith("_"):
            continue

        if isinstance(detail, Interface):
            if not verifyClass(detail, candidate, tentative=True):
                return False
        elif isinstance(detail, FunctionType):
            if name not in candidate.__dict__:
