    for column in spec_content["columns"]:
        if not isinstance(column, dict):
            raise IRValidatorException("Column must be a dictionary")
        if "name" not in column:
            raise IRValidatorException("Name field missing in column")
        if "type" not in column:
            raise IRValidatorException("Type field missing in column")

    # Return the validated data
    return {"name": spec_content["name"], "type": spec_content["type"], "columns": spec_content["columns"]}

def validate_from_file(yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    try:
        with open(yaml_file) as f:
