    except FileNotFoundError:
        raise IRValidatorException(f"File {yaml_file} not found")
    except yaml.YAMLException as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}")

    errors = []
    for required_field in cls.REQUIRED_FIELDS:
